select t.location_id locationId, t.location_name locationName, t.parent_id parentId,
       t.level, t.remark, t.community_id communityId, t.seq, t.status_cd statusCd
from shop_location t
where 1 = 1 and t.status_cd = '0'

    and t.location_id = #{locationId}


    and t.location_id in

        #{item}



    and t.parent_id = #{parentId}


    and t.community_id = #{communityId}


    and t.level = #{level}


    and t.location_name = #{locationName}


    and t.location_name like concat('%', #{locationNameLike}, '%')

order by t.seq asc, t.create_time desc

    limit #{page}, #{row}

select count(1) count
from shop_location t
where 1 = 1 and t.status_cd = '0'

    and t.location_id = #{locationId}


    and t.parent_id = #{parentId}


    and t.community_id = #{communityId}


    and t.level = #{level}


    and t.location_name = #{locationName}


    and t.location_name like concat('%', #{locationNameLike}, '%')

mapper.update:
update shop_location t set t.status_cd = #{statusCd}

    , t.location_name = #{locationName}


    , t.parent_id = #{parentId}


    , t.level = #{level}


    , t.remark = #{remark}


    , t.seq = #{seq}

where 1 = 1

    and t.location_id = #{locationId}
